-- Product_Id: 2254 (PROTEINI.SI KNEE WRAPS)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI KNEE WRAPS' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>High-quality elastic material that protects the knees and provides extra support and comfort during exercise</p></li><li><p>Adjustable – one size fits all</p></li><li><p>Sold as a pair!</p></li></ul><p>Knee wraps are designed to support the knees during weight exercises such as squats and deadlifts.</p><p>Made from durable cotton, these elastic wraps are fully adjustable and fasten with a Velcro closure.</p><p>They are sold as a pair. The wraps are 1.5 metres long and 8 cm wide, and when stretched they can reach a length of approximately 3 metres.</p><ul><li><p>High-quality elastic material for knee protection, extra support and comfort during exercise</p></li><li><p>Adjustable – one size fits all</p></li><li><p>Velcro closure</p></li><li><p>Sold as a pair</p></li><li><p><strong>Length:</strong> 150 cm</p></li><li><p><strong>Width:</strong> 8 cm</p></li></ul>"]' ELSE DescriptionEn END
