-- Product_Id: 2255 (PROTEINI.SI LADY SPORT BAG)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI LADY SPORT BAG' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Spacious sports bag – suitable for fitness, sports activities and travel</p></li><li><p>Very spacious main zip compartment for easy access</p></li><li><p>Removable, padded shoulder strap</p></li><li><p>Can also be carried as a backpack</p></li></ul><p>The spacious <strong>pink and black Proteini.si sports bag</strong> is made from durable polyester. It is suitable for fitness, other sports activities and travel. The bag has a spacious main zip compartment and two side compartments, suitable for storing damp clothes and shoes. The shoulder strap is padded for extra comfort and is adjustable in length. The bag also has two carry handles. The bottom is padded for extra protection.</p><p><strong>In addition</strong>, the bag has two adjustable shoulder straps hidden in the pocket on the bottom, so it can also be used as a backpack.</p><p><strong>Material:</strong> 100% polyester</p><p><strong>Dimensions:</strong> 50 × 28 × 30 cm</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2255;

-- Product_Id: 2256 (PROTEINI.SI LADY SPORT BAG, pink)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI LADY SPORT BAG, pink' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Multi-purpose, medium-sized cylindrical sports bag</p></li><li><p>Attractive pattern in pink, purple and red</p></li><li><p>Made from durable polyester</p></li><li><p>With practical pockets in different sizes and carrying straps</p></li></ul><p><strong>The Proteini.si women’s sports bag</strong> is a practical, durable, medium-sized bag with a cylindrical shape. It is made from durable polyester with a diamond pattern in which the colours blend into one another. Both sides carry the lettering “Proteini.si women”.</p><p>The bag is suitable for fitness, other sports and travel. It has a main zip compartment, two mesh side compartments suitable for storing damp clothes and shoes, and two small outer zip pockets for keeping small items, a wallet, phone and similar.</p><p>The shoulder strap is padded for extra comfort and is adjustable in length. The bag also has two carry handles. The bottom is padded for extra protection.</p><p><strong>Material:</strong> polyester, nylon</p><p><strong>Dimensions:</strong></p><ul><li><p><strong>Length:</strong> 47 cm</p></li><li><p><strong>Diameter:</strong> 26 cm</p></li></ul>"]' ELSE DescriptionEn END
WHERE Product_Id = 2256;

-- Product_Id: 2257 (PROTEINI.SI LIFTING STRAPS)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI LIFTING STRAPS' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Straps that help when lifting weights</p></li><li><p>Reduce the load on the fingers and wrists</p></li><li><p>For exercises such as deadlifts, lat pulldowns and rows</p></li></ul><p><strong>Lifting straps</strong> are bands that provide extra support when lifting weights.</p><p>They are made from soft material and are loop-shaped, which allows a more comfortable and secure grip when lifting.</p><p>They are especially useful and almost indispensable for deadlifts, lat pulldowns and rowing exercises.</p><p><strong>Size:</strong> universal</p><p><strong>Dimensions:</strong> 57 × 4–4.5 cm</p><p><strong>Colour:</strong> black</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2257;

-- Product_Id: 2258 (PROTEINI.SI PILL BOX)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI PILL BOX' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Organiser for storing tablets and capsules</p></li><li><p>5 compartments</p></li><li><p>Easy opening and secure closing</p></li><li><p><strong>Dimensions:</strong> 11 × 9.5 × 3 cm</p></li></ul><p><strong>PROTEINI.SI PILL BOX</strong> is a practical box with <strong>five compartments</strong> (2 larger and 3 smaller) in which you can <strong>store your supplements</strong> in tablet and capsule form.</p><p>The box has an <strong>attractive</strong> and <strong>modern</strong> design, is made from <strong>BPA-free plastic</strong> and is available in three colours – attractive <strong>yellow</strong> and <strong>pink</strong>, as well as classic <strong>black</strong>.</p><p><strong>Main features:</strong></p><ul><li><p>5 compartments for organising your food supplements</p></li><li><p>Attractive and modern design</p></li><li><p>Made from BPA-free plastic</p></li><li><p>Dishwasher safe</p></li><li><p>Push-button clasp for easy opening and secure closing</p></li><li><p>Suitable for everyday use and travel</p></li><li><p><strong>Dimensions:</strong> 11 × 9.5 × 3 cm</p></li></ul><p>Now you can carefree keep all the supplements you need close at hand to meet your daily needs for amino acids, vitamins and minerals.</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2258;

-- Product_Id: 2259 (PROTEINI.SI PUSH-UP BARS)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI PUSH-UP BARS' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Handles for doing push-ups</p></li><li><p>For strengthening the upper body (chest, triceps and shoulders)</p></li><li><p>Greater intensity and faster results</p></li><li><p>Provide greater safety and comfort during exercise</p></li></ul><p>Push-up bars are a very effective tool for strengthening the upper body (chest, triceps and shoulders). They are a better alternative to classic push-ups because they allow greater intensity and greater comfort during exercise, without direct pressure on the wrists and palms. With them you can do more repetitions than with classic push-ups.</p><p>In addition, the bars allow a greater range of motion during push-ups, making the exercise more challenging and encouraging faster muscle development. They can be used in different ways, depending on your goal and the muscle group you want to activate (chest, triceps or shoulders). Placing the bars closer together activates the triceps, while a wider placement – at shoulder width or wider – engages the shoulder muscles more.</p><p>If you do push-ups regularly, these bars will let you further increase your strength and range of motion while protecting your wrists and palms. That way you can focus more on your chest, shoulders and triceps.</p><p>The handles are covered with foam for a better grip and greater comfort. The covering also protects the floor and prevents slipping during exercise.</p><p><strong>FEATURES:</strong></p><ul><li><p><strong>Dimensions:</strong> 18 × 13 × 11 cm</p></li><li><p><strong>Material:</strong> metal, foam</p></li><li><p><strong>Colour:</strong> black</p></li></ul>"]' ELSE DescriptionEn END
WHERE Product_Id = 2259;

-- Product_Id: 2260 (PROTEINI.SI GRAB PADS)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI GRAB PADS' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Pads for an easier, more secure grip during training</p></li><li><p>Provide protection and comfort</p></li><li><p>Prevent blisters</p></li></ul><p><strong>Grab Pads</strong> are pads that allow a better grip when lifting weights.</p><p>They provide proper protection and comfort for the palms when lifting heavy weights.</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2260;

-- Product_Id: 2261 (PROTEINI.SI RESISTANCE BAND, 70cm, light difficulty (yellow))
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI RESISTANCE BAND, 70cm, light difficulty (yellow)' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Closed-loop elastic resistance band with a circumference of 70 cm</p></li><li><p>Suitable for full-body workouts</p></li><li><p>A popular training aid among women</p></li><li><p>Allows effective exercises for strengthening the thighs and glutes</p></li><li><p><strong>Difficulty:</strong> light (yellow)</p></li></ul><p>The closed-loop polyester resistance band allows full-body training. It can also be used to simulate gym machine exercises. The band creates good muscular resistance in every exercise and in both directions of movement. It allows movement in all directions, better distribution of muscular effort and correct execution of exercises.</p><p>It can be used to strengthen most muscle groups, for Pilates, muscle toning, medical rehabilitation or stretching at home and in the gym. It is especially popular with women because it allows very effective exercises for the thighs and glutes.</p><p><strong>FEATURES:</strong></p><ul><li><p><strong>Resistance:</strong> light</p></li><li><p><strong>Dimensions:</strong> circumference 70 cm, width 5.5 cm</p></li><li><p><strong>Material:</strong> polyester</p></li><li><p><strong>Colour:</strong> yellow</p></li></ul><p><strong>ADVANTAGES:</strong></p><ul><li><p>Multi-purpose use</p></li><li><p>Light and practical to carry</p></li><li><p>Comfortable to use</p></li><li><p>Does not slide up or down during exercise</p></li><li><p>Improves training quality and muscle flexibility</p></li></ul><p><strong>Net quantity:</strong> 1 elastic resistance band / pack</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2261;

-- Product_Id: 2262 (PROTEINI.SI SPEED JUMP ROPE)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI SPEED JUMP ROPE' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Speed jump rope with a bearing system for faster rotation</p></li><li><p>For warming up, cardio, strengthening the leg muscles and performing “Double Unders”</p></li><li><p>Adjustable rope length (up to 3 m)</p></li></ul><p><strong>The speed jump rope</strong> is a simple and effective training tool that helps develop speed, agility and coordination. It allows smooth, fast rotation through the air and is popular for warming up, cardio and strengthening the leg muscles. Thanks to its fast rotation, it is also used in CrossFit for performing “Double Unders” (two passes of the rope per jump).</p><p><strong>The speed jump rope</strong> is made from a 3-metre steel cable with a plastic coating, which allows jumping at high speed.</p><p>The bearing system allows smooth, fast rotation without tangling, which contributes to better results and faster muscle warm-up. The rope rotates at a 90° angle, which allows greater comfort and safety during exercise, and the longer handles make rotation easier.</p><p>The steel cable can be adjusted up to a length of 3 metres – simply shorten it to the desired length and secure it again with the screw. It is suitable for everyone.</p><p><strong>FEATURES:</strong></p><ul><li><p><strong>Rope length:</strong> 3 m</p></li><li><p><strong>Material:</strong> PVC-coated steel (rope), steel (handles)</p></li><li><p><strong>Colour:</strong> silver and black</p></li></ul>"]' ELSE DescriptionEn END
WHERE Product_Id = 2262;

-- Product_Id: 2263 (PROTEINI.SI WOMEN'S FITNESS BELT, PINK)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI WOMEN''S FITNESS BELT, PINK' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Polyester and leather fitness belt</p></li><li><p>Helps prevent hernia</p></li><li><p>Protects the spine when lifting weights</p></li><li><p>Designed for women</p></li></ul><p><strong>The Proteini.si women’s fitness belt</strong>, made from polyester and neoprene, is intended for more experienced exercisers who lift weights. It provides support and helps protect the back when using heavier weights.</p><ul><li><p>Ideal for lifting heavy weights</p></li><li><p>Provides support and protection for the back</p></li><li><p>Universal fit</p></li><li><p><strong>Available sizes:</strong> S, M</p></li></ul><p><strong>MEASUREMENTS:</strong></p><ul><li><p>S = 74–87 cm</p></li><li><p>M = 84–97 cm</p></li></ul><p><strong>MATERIAL:</strong></p><ul><li><p>Polyester: 50%</p></li><li><p>Neoprene: 40%</p></li><li><p>Other materials (metal, nylon): 10%</p></li></ul>"]' ELSE DescriptionEn END
WHERE Product_Id = 2263;

-- Product_Id: 2267 (DEDICATED UNSTOPPABLE PUMP)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'DEDICATED UNSTOPPABLE PUMP' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Legendary pre-workout supplement for a better “pump” effect</p></li><li><p>Premium ingredients</p></li><li><p>STIMULANT-FREE</p></li><li><p>Pure “pump” effect, no energy crash and no tingling</p></li><li><p>Multi-award-winning flavours</p></li><li><p>30 servings</p></li></ul><p><strong>Food supplement with sweeteners.</strong></p><p>UNSTOPPABLE PUMP™ contains exceptionally powerful ingredients, fully disclosed and dosed at the highest possible level for legendary results. No fillers, sugars or useless ingredients.</p><p>Feel for yourself, just a few minutes after taking UNSTOPPABLE PUMP™, why it carries exactly that name.</p><p><strong>NO STIMULANTS, NO ENERGY CRASH, NO TINGLING</strong></p><p>UNSTOPPABLE PUMP™ contains no stimulant ingredients and no ingredients that cause tingling, so you can easily fall asleep at night. It is perfectly balanced to help you finish your workouts without feeling overstimulated when you get home. All the physical performance benefits and an even better “pump” effect – with no stimulants!</p><p><strong>ULTRA-HIGH DOSES</strong></p><p>UNSTOPPABLE PUMP™ contains exceptionally powerful ingredients in doses that set high industry standards and that you will rarely find in other products, for legendary results. How powerful? How about a full 27,000 mg of active ingredients! We don’t skimp on dosing, so you don’t have to compromise on your performance.</p><p><strong>FULLY TRANSPARENT FORMULA</strong></p><p>All our formulas are fully disclosed. We have no need to hide behind fancy names like “proprietary blends”, which essentially give no accurate information about the real ingredients and their amounts.</p><p><strong>MULTI-AWARD-WINNING FLAVOURS</strong></p><p>Although UNSTOPPABLE PUMP™ contains large amounts of powerful ingredients, we also made sure a team of flavour experts did their job. The result is a stimulant-free pre-workout you will genuinely look forward to drinking.</p><p><strong>THE ULTIMATE EXPERIENCE</strong></p><p>The synergy between all the ingredients is what really sets UNSTOPPABLE PUMP™ apart from other products. Every ingredient is present at a maximum, exceptionally high dose and works in perfect harmony with the others. UNSTOPPABLE PUMP™ works differently from every product you have used so far.</p><p>No other stimulant-free pre-workout will give you the same impressive results that only UNSTOPPABLE PUMP™ can. This revolutionary product is truly one of a kind and, like all DEDICATED® products, is built for fast results. How fast? In just 5 minutes!</p><p><strong>Net quantity:</strong> 405 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'The dose is 1/2 scoop (13.5 g) for beginners and 1 full scoop (27 g) for advanced users.' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'BEGINNERS: Take 1/2 scoop 30 minutes before your workout. ADVANCED: Take 1 full scoop 30 minutes before your workout. WARNING: A varied, balanced diet and a healthy lifestyle are important. Food supplements are not a substitute for a varied diet. Please consult your doctor before use if you have a medical condition. Not recommended if you are pregnant or breastfeeding. Do not use if the safety seal is broken or missing. Use only as directed. Store in a cool, dry place. KEEP OUT OF REACH OF CHILDREN. Read the entire label before use.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Mix 1/2 scoop in 250 ml and 1 scoop in 200–300 ml of cold water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2267;

-- Product_Id: 2268 (DEDICATED UNSTOPPABLE PRE-WORKOUT)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'DEDICATED UNSTOPPABLE PRE-WORKOUT' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Legendary pre-workout supplement for improved performance</p></li><li><p>Premium ingredients</p></li><li><p>Muscle “pump”, performance, energy, focus and taste – ALL IN ONE</p></li><li><p>Multi-award-winning flavours</p></li><li><p>30 servings</p></li></ul><p><strong>UNSTOPPABLE™ – A legendary formula from the new generation of pre-workout supplements!</strong></p><p><strong>Food supplement with sweeteners.</strong></p><p><strong>Contains caffeine (195 mg/14 g; 390 mg/28 g). Not recommended for children or pregnant women.</strong></p><p>The legendary pre-workout for an instant performance boost has been upgraded in every respect – muscle “pump”, performance, energy, focus AND taste!</p><p>Breaking records, unlocking your true potential and pushing past your own limits – that is exactly what UNSTOPPABLE™ was created for.</p><ul><li><p><strong>FORMULATED WITH PREMIUM INGREDIENTS</strong></p></li><li><p><strong>HIGH DOSES AND EFFECTIVENESS</strong></p></li></ul><p>UNSTOPPABLE™ contains exceptionally powerful ingredients, fully disclosed and dosed at the highest possible level for legendary results.</p><p><strong>Feel it for yourself, just a few minutes after taking UNSTOPPABLE™.</strong></p><p><strong>ENERGY WITHOUT A CRASH</strong></p><p>Unstoppable™ contains a powerful combination of stimulant ingredients that help you give your maximum and push your workouts all the way. It is perfectly balanced to provide an even, long-lasting energy boost without leaving you drained after training.</p><p><strong>HIGH DOSES</strong></p><p>Unstoppable™ contains exceptionally powerful ingredients at the highest possible doses for legendary results. We don’t skimp on dosing, so you don’t have to compromise on your performance.</p><p><strong>FULLY TRANSPARENT FORMULA</strong></p><p>All our formulas are fully disclosed. We have no need to hide behind fancy names like “proprietary blends”, which essentially give no real information about the ingredients and their amounts. 100% free of empty marketing promises!</p><p><strong>MULTI-AWARD-WINNING FLAVOURS</strong></p><p>Although Unstoppable™ contains large amounts of powerful ingredients, we also made sure a team of flavour experts did their job. The result is a pre-workout you will genuinely look forward to drinking.</p><p><strong>BECOME UNSTOPPABLE</strong></p><p>Thanks to proven, effective ingredients at the highest possible doses, Unstoppable™ gives you an intense experience that will motivate you to break records and push past your own limits.</p><p>You don’t have to take only our word for it – Unstoppable™ has won multiple awards from leading industry experts and websites, who recognise it as a truly effective, record-breaking pre-workout!</p><p>Unstoppable™ was created with one single goal – to deliver the ultimate pre-workout experience... LIKE NOTHING YOU HAVE HAD BEFORE!</p><p><strong>THE ULTIMATE EXPERIENCE</strong></p><p>The synergy between all the ingredients is what really sets UNSTOPPABLE™ apart from other products. Every ingredient is present at a precisely defined maximum dose and works in perfect harmony with the others.</p><p>UNSTOPPABLE™ works differently from every product you have used so far. No other pre-workout will give you the same impressive results that only UNSTOPPABLE™ can.</p><p>UNSTOPPABLE™ is a truly unique and revolutionary product that, like all DEDICATED® products, delivers fast results!</p><p><strong>Feel the effect for yourself. It’s time to become UNSTOPPABLE!</strong></p><p><strong>ACTIVE INGREDIENTS:</strong></p><ul><li><p>L-citrulline</p></li><li><p>Beta-alanine</p></li><li><p>Betaine anhydrous</p></li><li><p>Caffeine anhydrous – enough caffeine to boost energy without overstimulation</p></li><li><p>Mango leaf extract (Zynamite™) – a revolutionary new stimulant extract, reported not to cause side effects</p></li><li><p>L-tyrosine</p></li><li><p>Vitamin B3 (niacin)</p></li><li><p>Potassium and sodium – for optimal hydration</p></li><li><p>Vitamin C</p></li><li><p>AstraGin® – an ingredient that can increase absorption, and with it the effectiveness of all the ingredients in UNSTOPPABLE™, helping them work more efficiently.</p></li></ul><p><em>A balanced and varied diet and a healthy lifestyle are important.</em></p><p><strong>Net quantity:</strong> 420 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'The dose is 1/2 scoop (14 g) for beginners and 1 full scoop (28 g) for advanced users.' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'BEGINNERS: Take 1/2 scoop 30 minutes before your workout. ADVANCED: Take 1 full scoop 30 minutes before your workout. WARNING: A varied, balanced diet and a healthy lifestyle are important. Food supplements are not a substitute for a varied diet. Please consult your doctor before use if you have a medical condition. Not recommended if you are pregnant or breastfeeding. Do not use if the safety seal is broken or missing. Use only as directed. Store in a cool, dry place. KEEP OUT OF REACH OF CHILDREN. Read the entire label before use. Contains caffeine (195 mg per 14 g; 390 mg per 28 g). This product should not be used in combination with caffeine or stimulants from other sources. Do not exceed a daily intake of 400 mg of caffeine.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Mix 1/2 scoop in 250 ml and 1 scoop in 200–300 ml of cold water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2268;

-- Product_Id: 2270 (BODY ATTACK 100% PURE CREATINE)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'BODY ATTACK 100% PURE CREATINE' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Creatine monohydrate</p></li><li><p>Micro-fine powder with no additives</p></li><li><p>Cologne List product</p></li></ul><p><strong>Food supplement with creatine monohydrate, intended for adults who engage in high-intensity physical activity.</strong></p><p><strong>Increase your maximum strength!</strong></p><p>Whether it’s the final sprint or the last rep of your workout, with Body Attack 100% Pure Creatine Powder you can push your limits and reach your best physical performance! The micro-fine creatine monohydrate powder impresses with its pure, additive-free composition and dissolves excellently in fruit juice or water, helping you stay one step ahead.</p><p>100% Pure Creatine is an excellent choice to support the following goals:</p><ul><li><p>Increasing strength</p></li><li><p>More intense training sessions</p></li><li><p>Maintaining muscle mass</p></li><li><p>Faster recovery</p></li></ul><p><strong>Who is 100% Pure Creatine suitable for?</strong></p><ul><li><p>Fitness enthusiasts</p></li><li><p>Athletes</p></li><li><p>Strength athletes</p></li><li><p>Endurance and team-sport athletes</p></li><li><p>People who want to gain weight</p></li></ul><p><strong>Creatine – white gold</strong></p><p>Creatine is a natural substance that the body itself produces from the amino acids glycine, arginine and methionine in the liver, kidneys and pancreas. There are several forms of creatine, but the monohydrate is especially easily absorbed by the body, which is why it is the active ingredient in 100% Pure Creatine. Take advantage of this to improve your physical performance during training.</p><p><strong>Clear benefits</strong></p><p>Increase your maximum strength during training and improve your speed in intense endurance training. 100% Pure Creatine is a truly versatile product and an excellent partner for everyone.</p><p><em>A balanced and varied diet and a healthy lifestyle are important.</em></p><p><strong>Net quantity:</strong> 300 g / 500 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'The serving size is 2 scoops (3.4 g).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Take 1 serving twice a day with plenty of fluid (300 ml), preferably before and after intense training. On non-training days, take 1 serving twice a day with plenty of fluid (300 ml) – the first in the morning straight after getting up and the second before bed. WARNING: Do not exceed the stated recommended daily dose. The product should not be used as a substitute for a balanced diet. Keep out of reach of children! After opening, use the product as soon as possible. Keep away from direct heat and light.' ELSE InstructionsForUseDescriptionEn END
WHERE Product_Id = 2270;

-- Product_Id: 2272 (OPTIMUM ELECTROLYTE POWDER)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'OPTIMUM ELECTROLYTE POWDER' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>An effective blend of electrolytes (sodium, magnesium, potassium) that supports hydration and energy levels</p></li><li><p>For intense or endurance training</p></li><li><p>No sugar and no unnecessary additives</p></li><li><p>Dissolves easily and refreshes</p></li></ul><p><strong>Food supplement with electrolytes, in powder form with sweetener, intended for preparing a drink.</strong></p><p><strong>What are electrolytes?</strong></p><p>Electrolytes are essential minerals, including sodium, potassium and magnesium, that play an important role in various physiological functions. This refreshing electrolyte powder is formulated to provide key minerals in precise amounts, helping you be ready before, during or after strenuous physical activity.</p><p><strong>Performance benefits:</strong></p><ul><li><p>Provides 400 mg sodium, 300 mg potassium** and 113 mg magnesium* per serving</p></li><li><p>Potassium contributes to normal muscle function**</p></li><li><p>Magnesium contributes to electrolyte balance and helps reduce tiredness and fatigue*</p></li><li><p>No sugar and no unnecessary additives</p></li></ul><p><strong>When to use this product?</strong></p><ul><li><p><strong>Before training:</strong> Prepare your body with essential electrolytes.</p></li><li><p><strong>During training:</strong> Support your mineral intake during long or intense workouts.</p></li><li><p><strong>After training:</strong> Replace minerals lost through sweat.</p></li></ul><p><strong>Why choose this product?</strong></p><p>With more than 35 years of experience in sports nutrition and a presence in more than 90 countries, Optimum Nutrition offers top quality you can rely on. This electrolyte formula dissolves quickly, mixes easily and is available in refreshing lemon and forest fruit flavours. It is designed to support your active lifestyle, with no added sugar and no unnecessary ingredients.</p><p><em>A balanced and varied diet and a healthy lifestyle are important.</em></p><p><strong>Net quantity:</strong> 33 servings (264 g)</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 8 g (~1 full scoop).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Recommended use: 1 serving daily. WARNING: Do not exceed the recommended daily dose. The product is not a substitute for a balanced diet. Keep out of reach of children! If you are taking medication or have a health condition, consult a healthcare professional before use. Do not use during pregnancy or breastfeeding. STORAGE: Store in a cool, dry place, protected from direct sunlight.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Add 1 serving to 450 ml of cold water and stir until the powder has completely dissolved.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2272;

-- Product_Id: 2273 (OLIMP GOLD-VIT B FORTE, 60 tabs)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'OLIMP GOLD-VIT B FORTE, 60 tabs' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li>B-group vitamin complex</li><li>Supports nutrient metabolism and energy production</li><li>Intended for athletes and people with a stressful lifestyle</li></ul><h3>.</h3><p>GOLD-VIT B FORTE is a food supplement in tablet form with a complex of B-group vitamins, which are necessary for numerous processes in the body to run properly. Vitamin B2, niacin and biotin contribute to the normal functioning of the nervous system and to the maintenance of normal skin. In addition, biotin contributes to normal macronutrient metabolism.</p><p>Vitamins B6 and B12 contribute to normal red blood cell formation. Folate contributes to normal blood formation and to normal amino acid synthesis, which is especially important during intense physical activity.</p><p>Source: https://en.olimp-labs.com/</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 1 tablet.' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Take 1 serving daily. WARNING: Do not exceed the recommended daily dose. Food supplements should not be used as a substitute for a varied and balanced diet. A varied and balanced diet and a healthy lifestyle are recommended. Keep out of reach of children.' ELSE InstructionsForUseDescriptionEn END
WHERE Product_Id = 2273;

-- Product_Id: 2274 (CH Alpha)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'CH Alpha' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<h3>ch</h3><p>CH-ALPHA<br>Degeneration of the cartilage in the joints can cause loss of elasticity and increased stiffness in the joints that carry the greatest load, such as the knees and hips. This can be caused by excessive exercise, repetitive movement or increased body weight, as well as by an inactive lifestyle without much movement. It usually begins in the third decade of life and progresses over the years.</p><p>What is cartilage?</p><p>Cartilage is a firm, elastic tissue that covers all the joints and protects the bones from rubbing against each other. Cartilage is a smooth surface that lets the bones glide finely when they move and helps absorb pressure during physical activity.</p><p>Articular cartilage contains type II collagen and proteoglycans in the intercellular substance, responsible for strength and elasticity.</p><p>This intercellular substance is made up mainly of water, type II collagen (which provides firmness and lubrication at the same time) and proteoglycans (which prevent compression).</p><p>It is vitally important to maintain normal collagen levels in the tissues of the bones, cartilage, ligaments and joints! Healthy, normal movement of the body is fundamental!</p><p>When the natural regenerative process cannot meet the body’s daily needs because of injuries, excess weight or overtraining, the connective tissue becomes damaged.</p><p>As connective tissue is lost, fluid is lost too and friction increases, leading to reduced elasticity and a gradual increase in discomfort and pain.</p><p>Special cells, chondrocytes, control the rate of cartilage regeneration in the joints and recognise changes in cartilage structure. When conditions change, chondrocytes respond by rebuilding the worn cartilage.</p><p>Unusually for any tissue in the body, cartilage contains no nerves or blood vessels. This contributes to very slow regeneration and makes treatment more difficult. Cartilage is an actively growing tissue and needs continuous regeneration to perform its function as protector of the joints.</p><p>Who benefits from CH-ALPHA?</p><p>Quite simply, anyone interested in improving their mobility and quality of life.</p><p>People who benefit from CH-ALPHA:</p><p>Those who work lifting heavy loads.</p><p>People who do repetitive and exhausting work.</p><p>People with excess body weight.</p><p>Physically inactive people.</p><p>Athletes.</p><p>Is CH-ALPHA safe to use?</p><p>According to medical studies, there are no known interactions with other medicines or any foods.</p><p>There are no reports of allergic reactions.</p><p>30 ampoules<br>Dosage: 1 ampoule per day</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Dosage: 1 ampoule per day' ELSE InstructionsForUseEn END
WHERE Product_Id = 2274;

-- Product_Id: 2275 (VAST V8 ULTRA)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'VAST V8 ULTRA' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>4-in-1 high-performance pre-workout booster</p></li><li><p>With 7 patented ingredients</p></li><li><p>With TriBsyn™ – beta-alanine without the tingling sensation</p></li><li><p>Perfect for long workouts and heavy physical loads</p></li><li><p>Tasty sugar-free drink</p></li><li><p>20 servings</p></li></ul><p><strong>Food supplement, especially intended for athletes. Powder for preparing a drink with amino acids and plant extracts, with sweeteners.</strong></p><p><strong>High caffeine content (300 mg/18.2 g). Not recommended for children or pregnant or breastfeeding women.</strong></p><p>V8 ULTRA marks the start of a new era in training. With 7 patented active ingredients, clinically proven doses and uncompromising action, it is intended for everyone who wants to go beyond standard limits.</p><p>V8 ULTRA is the first pre-workout in Europe to contain TriBsyn™ – a new form of beta-alanine with hydro-oleo technology that allows good absorption without the typical tingling sensation.</p><p><strong>4-IN-1 PRE-WORKOUT FORMULA</strong></p><p><strong>Performance. Focus. Muscle “pump”. Hydration.</strong></p><p>V8 ULTRA combines the latest technologies in a single high-performance formula. It is designed to deliver exactly the benefits that matter at every stage of your workout.</p><p>From the warm-up to the last rep, the 4-in-1 formula gives you the energy, mental clarity and endurance you need to get the most out of every workout.</p><p><strong>Reach your peak. Every time.</strong></p><p><strong>KEY ADVANTAGES:</strong></p><ul><li><p>Premium 4-in-1 high-performance pre-workout booster</p></li><li><p>The first formula on the market with 7 patented ingredients</p></li><li><p>With TriBsyn™ – latest-generation beta-alanine that does not cause a tingling sensation</p></li><li><p>Peak ATP®</p></li><li><p>300 mg PurCaf® – natural caffeine from green coffee beans¹</p></li><li><p>8 g citrulline malate, 2.5 g BetaPower® and S7® – amino acids and plant extracts</p></li><li><p>50 mg Senactiv® – a complex of plant extracts</p></li><li><p>1600 mg VitaCholine™</p></li><li><p>Electrolyte matrix of pink Himalayan salt, magnesium and potassium</p></li><li><p>Perfect for intense weight training, powerlifting, Hyrox and HIIT. Ideal for long workouts and heavy physical loads.</p></li><li><p>3 tasty sugar-free variants: black cherry & lime, blue raspberry, pink lemonade</p></li></ul><p><em>A balanced and varied diet and a healthy lifestyle are important.</em></p><p><strong>Net quantity:</strong> 364 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 1 scoop (18.2 g).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Consume 1 serving 20–30 minutes before training or sports activity. Recommended daily use: 1 serving. WARNING: High caffeine content (300 mg/18.2 g). Not recommended for children or pregnant or breastfeeding women. It is recommended not to consume more than 400 mg of caffeine per day. Do not exceed the recommended daily dose. The product should not be used as a substitute for a balanced diet. Keep out of reach of children! Store in a cool, dry place.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Mix 1 serving with 300 ml of water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2275;

-- Product_Id: 2276 (SPORTNAHRUNG SUPER BOOST)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'SPORTNAHRUNG SUPER BOOST' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>4-in-1 high-performance pre-workout booster</p></li><li><p>With 7 patented ingredients</p></li><li><p>With TriBsyn™ – beta-alanine without the tingling sensation</p></li><li><p>Perfect for long workouts and heavy physical loads</p></li><li><p>Tasty sugar-free drink</p></li><li><p>20 servings</p></li></ul><p><strong>Food supplement, especially intended for athletes. Powder for preparing a drink with amino acids and plant extracts, with sweeteners.</strong></p><p><strong>High caffeine content (300 mg/18.2 g). Not recommended for children or pregnant or breastfeeding women.</strong></p><p>V8 ULTRA marks the start of a new era in training. With 7 patented active ingredients, clinically proven doses and uncompromising action, it is intended for everyone who wants to go beyond standard limits.</p><p>V8 ULTRA is the first pre-workout in Europe to contain TriBsyn™ – a new form of beta-alanine with hydro-oleo technology that allows good absorption without the typical tingling sensation.</p><p><strong>4-IN-1 PRE-WORKOUT FORMULA</strong></p><p><strong>Performance. Focus. Muscle “pump”. Hydration.</strong></p><p>V8 ULTRA combines the latest technologies in a single high-performance formula. It is designed to deliver exactly the benefits that matter at every stage of your workout.</p><p>From the warm-up to the last rep, the 4-in-1 formula gives you the energy, mental clarity and endurance you need to get the most out of every workout.</p><p><strong>Reach your peak. Every time.</strong></p><p><strong>KEY ADVANTAGES:</strong></p><ul><li><p>Premium 4-in-1 high-performance pre-workout booster</p></li><li><p>The first formula on the market with 7 patented ingredients</p></li><li><p>With TriBsyn™ – latest-generation beta-alanine that does not cause a tingling sensation</p></li><li><p>Peak ATP®</p></li><li><p>300 mg PurCaf® – natural caffeine from green coffee beans¹</p></li><li><p>8 g citrulline malate, 2.5 g BetaPower® and S7® – amino acids and plant extracts</p></li><li><p>50 mg Senactiv® – a complex of plant extracts</p></li><li><p>1600 mg VitaCholine™</p></li><li><p>Electrolyte matrix of pink Himalayan salt, magnesium and potassium</p></li><li><p>Perfect for intense weight training, powerlifting, Hyrox and HIIT. Ideal for long workouts and heavy physical loads.</p></li><li><p>3 tasty sugar-free variants: black cherry & lime, blue raspberry, pink lemonade</p></li></ul><p><em>A balanced and varied diet and a healthy lifestyle are important.</em></p><p><strong>Net quantity:</strong> 364 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 3 scoops (20 g).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Consume 30 minutes before training. Do not consume on an empty stomach. The maximum daily amount is 1 serving (20 g). WARNING: Do not exceed the recommended daily dose. Food supplements are not a substitute for a balanced and varied diet. Keep out of reach of young children. Not to be consumed by pregnant or breastfeeding women, people under 18 or people with cardiovascular disorders. STORAGE: Store in a dark, dry place at a temperature below 25°C.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Dissolve 1 serving (20 g) in 500 ml of cold water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2276;

-- Product_Id: 2277 (SPORTNAHRUNG EAA LOADED)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'SPORTNAHRUNG EAA LOADED' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<p></p><ul><li>7.4 g amino acids per serving (15 g)</li><li>All 9 essential amino acids (EAA) + L-glutamine and taurine</li><li>With added magnesium and vitamin B6 to reduce tiredness and support normal energy-yielding metabolism</li><li>Refreshing fruit flavour</li><li>22 servings</li></ul><p><strong>EAA Loaded – 7.4 g amino acids. One formula. Refreshing fruit flavour.</strong></p><p>When you want more from your amino acid formula, choose EAA Loaded.</p><p>EAA Loaded combines all <strong>9 essential amino acids</strong> with the additional amino acids <strong>L-glutamine</strong> and <strong>taurine</strong>. A single 15 g serving therefore provides a total of <strong>7,469 mg of amino acids.</strong></p><p>Amino acids are the basic building blocks of proteins and play an important role in sports nutrition. Among them are the <strong>essential amino acids (EAA)</strong>, which the human body cannot produce on its own in sufficient amounts and which must therefore come from the diet. The essential amino acids are: <strong>leucine, isoleucine, valine, lysine, threonine, methionine, phenylalanine, tryptophan and histidine.</strong></p><p>For added value, the formula is enriched with <strong>magnesium</strong> and <strong>vitamin B6</strong>. Magnesium contributes to normal muscle and nervous system function and to the reduction of tiredness and fatigue, while vitamin B6 contributes to normal energy-yielding metabolism and to the reduction of tiredness and fatigue.</p><p>All of this is rounded off with a pleasant peach or strawberry/cherry flavour for a refreshing experience with every serving. EAA Loaded is intended for anyone looking for a high-quality, practical combination of amino acids and selected micronutrients in one formula.</p><p><strong>Why choose EAA Loaded?</strong></p><ul><li>7,469 mg amino acids per serving</li><li>All 9 essential amino acids (EAA)</li><li>Additional L-glutamine and taurine</li><li>191 mg magnesium per serving (51% RI)</li><li>1.62 mg vitamin B6 per serving (116% RI)</li><li>Refreshing fruit flavour</li><li>22 servings</li></ul><p><em>A varied and balanced diet and a healthy lifestyle are recommended.</em></p><p><strong>Net quantity:</strong> 330 g</p><p></p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 2 scoops (15 g).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Consume during physical activity. Let the drink stand briefly so the powder dissolves better. The maximum daily dose is 1 serving (15 g). WARNING: Do not exceed the recommended daily dose. The product should not be used as a substitute for a balanced diet. Keep out of reach of children! STORAGE: Store in a dark, dry place at a temperature of up to 25°C.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Dissolve 1 serving in 600–800 ml of water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2277;

-- Product_Id: 2278 (OLIMP CHELA-MAG B6 CRAMP, 20 шумливи таблети)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'OLIMP CHELA-MAG B6 CRAMP, 20 effervescent tablets' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>100 mg magnesium and 300 mg potassium per effervescent tablet</p></li><li><p>For normal muscle and nervous system function</p></li><li><p>Excellent absorption</p></li><li><p>With added vitamins B1, B2, B3, B6, B12 and biotin</p></li></ul><p><strong>FOR NORMAL MUSCLE FUNCTION</strong></p><p>Chela-Mag B6 Cramp is a food supplement in effervescent tablet form containing a highly absorbable form of magnesium as Albion amino acid chelate (magnesium bisglycinate), as well as a highly absorbable form of potassium. These ingredients contribute to normal muscle function and, together with vitamins B1, B2, B3, B6, B12 and biotin, support the normal functioning of the nervous system.</p><p>Scientific research has shown that <strong>magnesium</strong> is a mineral essential to human life and takes part in almost all processes in the body. It is important for normal muscle and nervous system function, helps maintain electrolyte balance and contributes to protein synthesis. It also contributes to the reduction of tiredness and fatigue. Its presence is also necessary to maintain normal bones and teeth.</p><p><strong>Vitamin B6</strong> takes part in the absorption of magnesium from the gastrointestinal tract and, together with magnesium, is involved in many processes in the body.</p><p><strong>Potassium</strong> plays an important role in muscle and nervous system function. It also contributes to the maintenance of normal blood pressure.</p><p>Source: https://en.olimp-labs.com/</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 1 tablet.' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'WARNING: Do not exceed the recommended daily dose. Food supplements should not be used as a substitute for a varied and balanced diet. A varied and balanced diet and a healthy lifestyle are recommended. Keep out of reach of children. Do not use in case of hypersensitivity to any of the ingredients.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Dissolve 1 serving in 200 ml of water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2278;

-- Product_Id: 2279 (SPORTNAHRUNG CREATINE CHEWABLE TABLETS)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'SPORTNAHRUNG CREATINE CHEWABLE TABLETS' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Tasty orange or cherry flavoured chewable creatine tablets</p></li><li><p>Support muscle growth and maintenance</p></li><li><p>Increase physical performance</p></li><li><p>Ideal for use on the go</p></li></ul><p><strong>Food supplement with creatine, sugars and sweeteners.</strong></p><p>The new chewable creatine tablets from sportnahrung.at are ideal for all athletes who want extra support in reaching their sports goals. Creatine supports muscle growth, contributes to the maintenance of muscle mass and increases physical performance.</p><p>The practical chewable tablet form, with a great orange or cherry flavour, makes it easy to take your creatine with you wherever you go.</p><p><em>A balanced and varied diet and a healthy lifestyle are important.</em></p><p><strong>Net quantity:</strong> 200 tablets</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 4 tablets.' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Take 1 serving daily, between meals or straight after training. When using creatine, ensure sufficient daily fluid intake. WARNING: Use is recommended only for physically active adults and should be limited to a maximum of 8 weeks, followed by a break of at least 4 weeks. Creatine increases physical performance in successive bursts of short-term, very high-intensity exercise (the beneficial effect is obtained with a daily intake of 3 g of creatine). Do not exceed the recommended daily dose. The product should not be used as a substitute for a balanced diet. Keep out of reach of children! Store in a cool, dry place. Do not expose to direct sunlight.' ELSE InstructionsForUseDescriptionEn END
WHERE Product_Id = 2279;

-- Product_Id: 2280 (PROTEINI.SI PROTEIN BROWNIE)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI PROTEIN BROWNIE' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li>Rich, moist dark chocolate brownie</li><li>High in protein</li><li>Soft and moist texture</li><li>Low in sugars</li><li>Ideal as a practical snack on the go</li></ul><p><strong>High-protein bakery product with sugar and sweeteners.</strong></p><p>Enjoy the rich taste of dark chocolate while getting an extra serving of protein. Our Protein Brownie combines a soft, moist texture with an intense chocolate flavour, making it the ideal snack for an active lifestyle, after training or whenever you want something sweet without compromising your diet.</p><p>Made with egg white, whey protein and almond flour, each brownie provides 17 g of protein per 100 g and contributes to the maintenance and recovery of muscles. It is sweetened with a combination of sugar and sweeteners and offers great taste with only 2 g of sugars per 100 g.</p><p><strong>Why you’ll love it:</strong></p><ul><li>Rich dark chocolate flavour</li><li>High in protein – 17 g per 100 g</li><li>Only 2 g of sugars per 100 g</li><li>Soft and moist texture</li><li>With chocolate pieces</li><li>Great as a snack, dessert or after training</li></ul><p><em>A balanced and varied diet and a healthy lifestyle are important.</em></p><p><strong>Net quantity:</strong> 60 g / 15 x 60 g</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2280;

-- Product_Id: 2281 (USN CREATINE MONOHYDRATE - RED FRUIT PUNCH)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'USN CREATINE MONOHYDRATE - RED FRUIT PUNCH' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Micronised creatine monohydrate</p></li><li><p>Flavoured version – available in two tasty fruit flavours</p></li><li><p>Helps maintain energy levels during muscle contractions</p></li><li><p>Helps increase muscle mass</p></li><li><p>Fast absorption and recovery</p></li></ul><p><strong>Food supplement with creatine monohydrate, with sweeteners.</strong></p><p>USN’s micronised creatine monohydrate, in pure form and with high absorption, <strong>is now also available in a flavoured version</strong>, in <strong>two juicy fruit flavours</strong> – red fruit punch and tropical.</p><p>With a daily intake of at least 3 g of creatine, creatine increases physical performance in successive short bursts of high-intensity exercise. During muscle contractions, it helps maintain balanced ATP levels.</p><p>Creatine monohydrate supplementation is safe and suitable for anyone who trains in short, intense intervals. We recommend taking 3–5 g of creatine monohydrate straight after training, together with whey protein and carbohydrates, for optimal nutrient absorption and improved recovery.</p><p>Creatine is a nitrogenous organic compound found naturally in all vertebrates. The highest concentrations are present in muscle tissue. Creatine serves as a high-energy compound that provides quick energy, especially for muscle tissue, where a relatively large amount of ATP needs to be used in a short period. Taking creatine as a supplement increases the concentration of creatine in the muscles. Creatine can, to a certain extent, increase muscle strength, especially in anaerobic (short-duration) sports activities. It also increases muscle mass by increasing water retention in the muscles.</p><p><strong>Net quantity:</strong> 500 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'The serving size is 1 scoop (6.3 g).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Do not consume more than 4 servings per day. It is important to drink enough fluids every day. WARNING: Consult your doctor before use if you are taking medication or have been diagnosed with a medical condition. Not recommended for pregnant or breastfeeding women or people under 18. Do not exceed the recommended daily dose. Food supplements should not be used as a substitute for a balanced and varied diet and a healthy lifestyle. Keep out of reach of children! Store in a cool, dry place.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Mix 1 serving (6.3 g) with 250 ml of cold water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2281;

-- Product_Id: 2283 (PROTEINI.SI RESISTANCE BAND, 70cm, medium difficulty (green))
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI RESISTANCE BAND, 70cm, medium difficulty (green)' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Closed-loop elastic resistance band with a 70 cm circumference</p></li><li><p>Suitable for full-body training</p></li><li><p>A popular training aid among women</p></li><li><p>Allows effective exercises to strengthen the thighs and glutes</p></li><li><p><strong>Resistance:</strong> medium (green)</p></li></ul><p>The closed-loop polyester resistance band allows full-body training. It can also be used to simulate exercises on gym machines. The band provides good resistance when activating the muscles in both directions of movement. It allows movement in all directions, better distribution of muscle effort and correct execution of exercises.</p><p>It can be used to strengthen most muscle groups, for Pilates, muscle toning, medical rehabilitation or stretching at home and in the gym. It is especially popular with women because it allows very effective exercises for the thighs and glutes.</p><p><strong>FEATURES:</strong></p><ul><li><p><strong>Resistance:</strong> medium</p></li><li><p><strong>Dimensions:</strong> circumference 70 cm, width 5.5 cm</p></li><li><p><strong>Material:</strong> polyester</p></li><li><p><strong>Colour:</strong> green</p></li></ul><p><strong>ADVANTAGES:</strong></p><ul><li><p>Multi-purpose use</p></li><li><p>Light and practical to carry</p></li><li><p>Comfortable to use</p></li><li><p>Does not slide up or down during exercise</p></li><li><p>Improves training quality and muscle flexibility</p></li></ul><p><strong>Net quantity:</strong> 1 elastic resistance band / pack</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2283;

-- Product_Id: 2284 (PROTEINI.SI RESISTANCE BAND, 70cm, X-heavy difficulty (black))
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI RESISTANCE BAND, 70cm, X-heavy difficulty (black)' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Closed-loop elastic resistance band with a 70 cm circumference</p></li><li><p>Suitable for full-body training</p></li><li><p>A popular training aid among women</p></li><li><p>Allows effective exercises to strengthen the thighs and glutes</p></li><li><p><strong>Resistance:</strong> extra heavy (black)</p></li></ul><p>The closed-loop polyester resistance band allows full-body training. It can also be used to simulate exercises on gym machines. The band creates good muscle resistance in every exercise and in both directions of movement. It allows movement in all directions, better distribution of muscle effort and correct execution of exercises.</p><p>It can be used to strengthen most muscle groups, for Pilates, muscle toning, medical rehabilitation or stretching at home and in the gym. It is especially popular with women because it allows very effective exercises for the thighs and glutes.</p><p><strong>FEATURES:</strong></p><ul><li><p><strong>Resistance:</strong> extra heavy</p></li><li><p><strong>Dimensions:</strong> circumference 70 cm, width 5.5 cm</p></li><li><p><strong>Material:</strong> polyester</p></li><li><p><strong>Colour:</strong> black</p></li></ul><p><strong>ADVANTAGES:</strong></p><ul><li><p>Multi-purpose use</p></li><li><p>Light and practical to carry</p></li><li><p>Comfortable to use</p></li><li><p>Does not slide up or down during exercise</p></li><li><p>Improves training quality and muscle flexibility</p></li></ul><p><strong>Net quantity:</strong> 1 elastic resistance band / pack</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2284;

-- Product_Id: 2285 (PROTEINI.SI BOOTY HIP BAND, M, TURQUOISE)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI BOOTY HIP BAND, M, TURQUOISE' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Fabric elastic band for hip and glute training</p></li><li><p>For muscle toning, body shaping and increased glute activation during exercise</p></li><li><p>Available in 3 different sizes, depending on your choice of exercises and the desired intensity</p></li><li><p>Durable and comfortable, does not roll up or slip</p></li><li><p>Multi-purpose use</p></li></ul><p>The Proteini.si booty hip band is a fabric elastic training band that is an indispensable aid for training at home and in the gym.</p><p><strong>FEATURES:</strong></p><ul><li><p>3 different sizes, depending on your choice of exercises and intensity:</p><ul><li><p><strong>S (pink)</strong> – 33 × 7.6 cm – high resistance: narrow squat</p></li><li><p><strong>M (turquoise)</strong> – 38 × 7.6 cm – medium resistance: side leg raise, clamshell, lateral band walk</p></li><li><p><strong>L (grey)</strong> – 43 × 7.6 cm – low resistance: lunge, wide squat</p></li></ul></li><li><p><strong>Material:</strong> polyester and latex</p></li></ul><p><strong>ADVANTAGES:</strong></p><ul><li><p><strong>DURABILITY:</strong> The sturdy fabric is interwoven with special elastic fibres that allow a wide range of motion. The bands are designed not to tear during use.</p></li><li><p><strong>COMFORT:</strong> The fabric is sturdy, yet soft and pleasant on the skin. It does not pinch, tear, roll up or slip, so you can focus on your workout instead of constantly adjusting your equipment.</p></li><li><p><strong>DOES NOT ROLL UP:</strong> The large width and the inner latex grip layer prevent the band from rolling up during exercise.</p></li><li><p><strong>MULTI-PURPOSE USE:</strong> Can be used for Insanity, Pilates, CrossFit, Beachbody and glute workouts. Ideal for fitness, glute exercises and squats.</p></li></ul><p><strong>BENEFITS:</strong></p><ul><li><p><strong>GREATER GLUTE ACTIVATION</strong> – up to 400%.</p></li><li><p><strong>STRENGTHENING AND TONING:</strong> The bands help tone and strengthen the legs, glutes, thighs, calves, quadriceps, hamstrings, core muscles, the muscles around the hips, the abductors, arms and shoulders. They are easy to use and suitable for everyone, from beginners to experienced exercisers.</p></li><li><p><strong>IMPROVED MOBILITY, FLEXIBILITY AND STRENGTH:</strong> Excellent for hip stretching and for exercises involving the knees, muscles and joints. It can help reduce the risk of injury or be used after a sports or other injury. Before starting an exercise programme during recovery, it is best to consult a doctor or physiotherapist. Ideal for physical therapy and rehabilitation at home.</p></li><li><p><strong>FAT BURNING:</strong> By training the largest muscle groups, you can indirectly stimulate the fat-burning process.</p></li></ul><p><strong>Net quantity:</strong> 1 hip and glute training band / pack</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2285;

-- Product_Id: 2286 (PROTEINI.SI BOOTY HIP BAND, L, GRAY)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI BOOTY HIP BAND, L, GRAY' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Fabric elastic band for hip and glute training</p></li><li><p>For muscle toning, body shaping and increased glute activation during exercise</p></li><li><p>Available in 3 different sizes, depending on your choice of exercises and the desired intensity</p></li><li><p>Durable and comfortable, does not roll up or slip</p></li><li><p>Multi-purpose use</p></li></ul><p>The Proteini.si booty hip band is a fabric elastic training band that is an indispensable aid for training at home and in the gym.</p><p><strong>FEATURES:</strong></p><ul><li><p>3 different sizes, depending on your choice of exercises and intensity:</p><ul><li><p><strong>S (pink)</strong> – 33 × 7.6 cm – high resistance: narrow squat</p></li><li><p><strong>M (turquoise)</strong> – 38 × 7.6 cm – medium resistance: side leg raise, clamshell, lateral band walk</p></li><li><p><strong>L (grey)</strong> – 43 × 7.6 cm – low resistance: lunge, wide squat</p></li></ul></li><li><p><strong>Material:</strong> polyester and latex</p></li></ul><p><strong>ADVANTAGES:</strong></p><ul><li><p><strong>DURABILITY:</strong> The sturdy fabric is interwoven with special elastic fibres that allow a wide range of motion. The bands are designed not to tear during use.</p></li><li><p><strong>COMFORT:</strong> The fabric is sturdy, yet soft and pleasant on the skin. It does not pinch, tear, roll up or slip, so you can focus on your workout instead of constantly adjusting your equipment.</p></li><li><p><strong>DOES NOT ROLL UP:</strong> The large width and the inner latex grip layer prevent the band from rolling up during exercise.</p></li><li><p><strong>MULTI-PURPOSE USE:</strong> Can be used for Insanity, Pilates, CrossFit, Beachbody and glute workouts. Ideal for fitness, glute exercises and squats.</p></li></ul><p><strong>BENEFITS:</strong></p><ul><li><p><strong>GREATER GLUTE ACTIVATION</strong> – up to 400%.</p></li><li><p><strong>STRENGTHENING AND TONING:</strong> The bands help tone and strengthen the legs, glutes, thighs, calves, quadriceps, hamstrings, core muscles, the muscles around the hips, the abductors, arms and shoulders. They are easy to use and suitable for everyone, from beginners to experienced exercisers.</p></li><li><p><strong>IMPROVED MOBILITY, FLEXIBILITY AND STRENGTH:</strong> Excellent for hip stretching and for exercises involving the knees, muscles and joints. It can help reduce the risk of injury or be used after a sports or other injury. Before starting an exercise programme during recovery, it is best to consult a doctor or physiotherapist. Ideal for physical therapy and rehabilitation at home.</p></li><li><p><strong>FAT BURNING:</strong> By training the largest muscle groups, you can indirectly stimulate the fat-burning process.</p></li></ul><p><strong>Net quantity:</strong> 1 hip and glute training band / pack</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2286;

-- Product_Id: 2287 (DEDICATED LIQUID GRIP CHALK)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'DEDICATED LIQUID GRIP CHALK' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Liquid chalk (magnesium)</p></li><li><p>Dries quickly and lasts a long time</p></li><li><p>Keeps palms dry during exercise</p></li><li><p>Ensures a secure grip when training</p></li><li><p>For weightlifting, climbing, gymnastics, pole dancing, bowling and more</p></li><li><p><strong>Net quantity:</strong> 250 ml</p></li></ul><p><strong>Liquid chalk.</strong></p><p>Liquid Grip Chalk keeps your palms dry and improves your grip during training. It is suitable for weightlifting as well as other sports where a secure grip and preventing sweaty palms are needed.</p><p>The chalk absorbs excess sweat and improves grip during exercise. It stops equipment slipping from your hands, making your workout safer and more effective! Just apply a small amount of the liquid to ensure a secure grip during training.</p><p><strong>FEATURES:</strong></p><ul><li><p>High-quality liquid chalk</p></li><li><p>Much more practical than block or powder chalk</p></li><li><p>Absorbs excess sweat</p></li><li><p>Provides a good grip</p></li><li><p>Long-lasting effect</p></li><li><p>Suitable for use in various sports (multi-purpose)</p></li></ul><p><strong>Net quantity:</strong> 250 ml</p>"]' ELSE DescriptionEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'DIRECTIONS: Shake the bottle vigorously before each use. Apply a small amount to clean, dry palms and let it dry completely. The product is ready to use once the chalk has dried. After training, wash off with warm water and soap. WARNING: Highly flammable liquid and vapour. Causes serious eye irritation. May cause drowsiness or dizziness. May cause an allergic skin reaction. Keep away from all sources of ignition. Avoid breathing the vapour. KEEP OUT OF REACH OF CHILDREN. Avoid contact with eyes and broken skin. If the product gets into the eyes, rinse immediately with water. Test the product on a small area before full use. Stop use if irritation or a skin rash appears. Do not swallow. For external use only. Let the product dry completely before touching equipment. Keep tightly closed in a cool, well-ventilated place.' ELSE InstructionsForUseDescriptionEn END
WHERE Product_Id = 2287;

-- Product_Id: 2289 (PROTEINI.SI SHAKER PLUS, 550ml)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI SHAKER PLUS, 550ml' ELSE NameEn END,
