-- Product_Id: 2299 (BATTERY SUPERCHARGED PUMP)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'BATTERY SUPERCHARGED PUMP' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Refreshing tropical-flavoured drink</p></li><li><p>A combination of amino acids, creatine and caffeine – all in one drink</p></li><li><p>Contains creatine to support physical performance during high-intensity exercise</p></li><li><p>Quick and easy to prepare</p></li><li><p>Suitable as part of an active lifestyle</p></li></ul><p><strong>Food supplement with sweetener.</strong></p><p>Contains caffeine (150 mg per serving). Not recommended for children or pregnant women.</p><p>This powdered food supplement with a refreshing tropical flavour is intended for anyone who wants to step up their sports routine. The advanced combination of amino acids, creatine and caffeine makes a practical, tasty drink before training or during the active part of your day.</p><p>It contains creatine, which, with a daily intake of 3 g, contributes to increased physical performance in successive bursts of short-term, high-intensity exercise. The added caffeine provides the characteristic pre-workout feeling, getting you ready to train.</p><p><strong>MAIN ADVANTAGES:</strong></p><ul><li><p>Advanced pre-workout formula with amino acids, creatine and caffeine</p></li><li><p>Refreshing tropical flavour: orange, lemon and pineapple</p></li><li><p>Creatine contributes to improved physical performance during short-term, high-intensity exercise (with a daily intake of 3 g)</p></li><li><p>An ideal choice before training or as part of an active lifestyle</p></li><li><p>Quick and easy preparation of a tasty drink</p></li></ul><p><strong>MAIN INGREDIENTS:</strong></p><ul><li><p>Creatine contributes to improved physical performance during intense physical activity (with a daily intake of 3 g)</p></li><li><p>Caffeine helps increase alertness and improve concentration during training</p></li><li><p>The amino acids L-citrulline, beta-alanine, L-tyrosine and L-arginine are often part of pre-workout formulas for active people</p></li><li><p>Synephrine – a natural compound obtained from bitter orange (<em>Citrus aurantium</em>)</p></li></ul><p><em>A varied and balanced diet and a healthy lifestyle are recommended.</em></p><p><strong>Net quantity:</strong> 300 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 2 scoops (10 g).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Consume 1 serving 30 minutes before training. Do not consume on an empty stomach. The maximum daily amount is 1 serving (10 g). WARNING: Do not exceed the recommended daily dose. Food supplements are not a substitute for a balanced and varied diet. Keep out of reach of young children. Not recommended for pregnant or breastfeeding women, people under 18 or people with cardiovascular disease. Store in a dark, dry place at a temperature below 25°C.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Dissolve 1 serving in 500 ml of water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2299;

-- Product_Id: 2300 (BATTERY STIM-FREE PUMP)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'BATTERY STIM-FREE PUMP' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>A “clean” pre-workout for serious training</p></li><li><p>100% stimulant-free – no caffeine and no energy crash</p></li><li><p>Formula with amino acids and creatine</p></li><li><p>Refreshing citrus flavour (orange and lemon)</p></li><li><p>Easy to prepare, for maximum training readiness</p></li></ul><p><strong>Food supplement with sweetener.</strong></p><p>Stim-Free Pump is the right choice when you want a maximum workout without compromise and without stimulants. No caffeine, no sudden energy crash – just focus on training and the feeling that you can give even more, at any time of day, even in the evening.</p><p>The advanced combination of citrulline, beta-alanine, arginine, tyrosine and creatine is designed for everyone who takes training seriously. This is a pre-workout with a “clean” formula – no unnecessary additives, only proven ingredients like those used in the best formulas.</p><p>When you don’t want stimulation but still want a real pre-workout experience, Stim-Free Pump is the right choice.</p><p>It contains creatine, which, with a daily intake of 3 g, contributes to increased physical performance in successive bursts of short-term, high-intensity exercise.</p><p><strong>ADVANTAGES:</strong></p><ul><li><p>Caffeine-free – a stimulant-free formula</p></li><li><p>An alternative to classic pre-workouts, suitable for use at any time of day</p></li><li><p>Refreshing citrus flavour (orange and lemon)</p></li><li><p>Contains creatine monohydrate</p></li><li><p>Quick and easy drink preparation</p></li></ul><p><strong>KEY INGREDIENTS:</strong></p><ul><li><p>L-citrulline DL-malate – a core ingredient in advanced pre-workout formulas</p></li><li><p>Beta-alanine – a popular choice for intense workouts</p></li><li><p>Creatine monohydrate – to support physical performance during high-intensity exercise (with a daily intake of 3 g)</p></li><li><p>L-arginine – an amino acid often included in sports supplements</p></li><li><p>L-tyrosine – an amino acid associated with an active lifestyle</p></li></ul><p>A varied and balanced diet and a healthy lifestyle are recommended.</p><p><strong>Net quantity:</strong> 300 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 2 scoops (10 g).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Consume 1 serving 30 minutes before training. The maximum daily amount is 1 serving (10 g).

WARNING: Do not exceed the recommended daily dose. Food supplements are not a substitute for a balanced and varied diet. Keep out of reach of young children. Not recommended for pregnant or breastfeeding women or children under 18.

STORAGE: Store in a dark, dry place at a temperature below 25°C.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Dissolve 1 serving in 500 ml of water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2300;

