-- Product_Id: 2302 (USN QHUSH PRE-WORKOUT, 220g)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'USN QHUSH PRE-WORKOUT, 220g' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>High-caffeine pre-workout and intra-workout supplement</p></li><li><p><strong>250 mg caffeine per serving</strong></p></li><li><p>With vitamins, beta-alanine, L-arginine and L-citrulline</p></li><li><p>For better focus and physical performance</p></li><li><p>20 servings</p></li></ul><p><strong>Food supplement with amino acids, plant extracts, caffeine and vitamins, with sweeteners.</strong></p><p>Contains caffeine (250 mg/11 g). Not recommended for children or pregnant or breastfeeding women.</p><p>Improve your training performance with a top pre-workout drink designed to take your energy and concentration to a higher level.</p><p>USN QHUSH Black is a pre-workout powder that provides excellent support for intense workouts in the gym, at home or before a run.</p><p><strong>HIGH STIMULATION LEVEL</strong></p><p>QHUSH Black contains 250 mg of caffeine in every serving, providing a strong energy boost before your next workout.</p><p><strong>FOCUS WHEN YOU NEED IT MOST</strong></p><p>QHUSH not only provides a strong energy boost, it also contains L-theanine (from green tea extract), which helps maintain a high level of concentration while you work towards your goals.</p><p><strong>ADVANCED FORMULA</strong></p><p>This is not an ordinary high-caffeine energy drink, but an advanced pre-workout formula. Enjoy a combination of training-support ingredients, including beta-alanine, L-arginine and L-citrulline, as well as vitamins B6 and B12, which contribute to the reduction of tiredness and fatigue.</p><p>A balanced and varied diet and a healthy lifestyle are important.</p><p><strong>Net quantity:</strong> 220 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 1 scoop (11 g).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'For best results, consume 30 minutes before training. After opening, use the product within 1 month.

WARNINGS: Contains caffeine (250 mg/11 g). Not recommended for children or pregnant or breastfeeding women. For adults only. Do not exceed 400 mg of caffeine per day from all sources (200 mg per day for pregnant and breastfeeding women). As with all food supplements, consult a doctor before use, especially if you have health problems and/or are taking medication. Do not exceed 1 serving (11 g) per day. Maintain adequate hydration. Suitable for vegetarians and vegans. Do not exceed the recommended daily dose. The product should not be used as a substitute for a balanced diet. Keep out of reach of children!' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Mix 1 scoop (11 g) with 250 ml of water. Shake well for 30 seconds.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2302;

-- Product_Id: 2303 (USN QHUSH ENERGY)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'USN QHUSH ENERGY' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Energy drink with a HIGH CAFFEINE CONTENT (150 mg per can)</p></li><li><p>With vitamins, amino acids and plant extracts</p></li><li><p>For more energy, focus and motivation</p></li><li><p>To help you cope with mental and physical effort</p></li></ul><p>Carbonated non-alcoholic drink with vitamins, amino acids, plant extracts and caffeine, with sweeteners. High caffeine content (30 mg/100 ml). Not recommended for children or pregnant or breastfeeding women.</p><p>QHUSH Energy, with 150 mg of caffeine per can, provides an exceptional energy boost in the form of a tasty carbonated drink with no sugar, carbohydrates or calories. Enjoy it whenever you need energy, focus and motivation, whether you are training, working in the office, studying or gaming. The drink is suitable for people with an active lifestyle.</p><p>In addition to caffeine, the drink contains:</p><ul><li><p>B-group vitamins (niacin, B6, B12 and pantothenic acid), which contribute to the normal functioning of the nervous system and normal psychological function, to the reduction of tiredness and fatigue, and to normal mental performance.</p></li><li><p>Taurine</p></li><li><p>Carnitine</p></li><li><p>Theanine</p></li><li><p>Ginseng</p></li></ul><p>Some flavours of the drink also contain:</p><ul><li><p>Vitamin C (Electric Blue Gaming flavour) – contributes to normal psychological function, the reduction of tiredness and fatigue, and the normal function of the immune system during and after intense physical exercise. The beneficial effect is obtained with a daily intake of 200 mg in addition to the recommended daily intake of vitamin C.</p></li><li><p>Tyrosine and phosphatidylserine (Glacier flavour)</p></li></ul><p>A balanced and varied diet and a healthy lifestyle are important.</p><p>The composition depends on the flavour.</p><p>Net quantity: 500 ml / 24 × 500 ml</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 1 can (500 ml).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Consume when you need energy and concentration. Consume in moderation. Do not exceed the maximum recommended daily dose (1 can). Serve chilled. After opening, keep refrigerated and consume within 48 hours. WARNING: Not recommended for people sensitive to caffeine. Do not exceed 400 mg of caffeine per day from all sources (200 mg per day for pregnant and breastfeeding women). Consume as part of a balanced, healthy lifestyle. Store in a cool place.' ELSE InstructionsForUseDescriptionEn END
WHERE Product_Id = 2303;

-- Product_Id: 2304 (SPORTNAHRUNG MAGNESIUM BISGLYCINATE (NEW))
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'SPORTNAHRUNG MAGNESIUM BISGLYCINATE (NEW)' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Food supplement with magnesium</p></li><li><p>For bone health, muscle recovery, energy production and normal nervous system function</p></li><li><p>30-day supply</p></li></ul><p><strong>Food supplement.</strong></p><p>Magnesium provides comprehensive support for bone health, muscle recovery, energy production and nervous system balance.</p><p><strong>BENEFITS OF MAGNESIUM:</strong></p><ul><li><p>Helps maintain healthy bones and normal immune system function.</p></li><li><p>Helps relax muscles, reduce cramps and ease tension.</p></li><li><p>Supports proper hydration and helps maintain normal blood pressure.</p></li><li><p>Contributes to cardiovascular health, helps stabilise energy levels, reduce tiredness and improve nervous system function.</p></li></ul><p>A varied and balanced diet and a healthy lifestyle are recommended.</p><p><strong>Net quantity:</strong> 120 capsules</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 4 capsules.' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Take 4 capsules with a glass of water after training or before bed.

WARNINGS: Do not exceed the recommended daily dose. Food supplements are not a substitute for a balanced and varied diet and a healthy lifestyle. Keep out of reach of young children.

STORAGE: Store in a dark, dry place at a temperature below 25°C.' ELSE InstructionsForUseDescriptionEn END
WHERE Product_Id = 2304;

-- Product_Id: 2305 (BATTERY MAGNESIUM BISGLYCINATE)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'BATTERY MAGNESIUM BISGLYCINATE' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Magnesium bisglycinate – a high-quality organic form of magnesium</p></li><li><p>Good absorption and gentle on the stomach</p></li><li><p>Supports muscles after exercise and physical exertion</p></li><li><p>Helps reduce tiredness and fatigue</p></li><li><p>For active people, athletes and everyday well-being</p></li><li><p>1-month supply</p></li></ul><p><strong>Food supplement.</strong></p><p>Magnesium is an essential mineral for active people, as it contributes to normal muscle function, helps reduce tiredness and fatigue and supports recovery after physical exertion. It is suitable for anyone who wants to support their body in everyday activities, sport and relaxation.</p><p>The product contains magnesium in the form of magnesium bisglycinate, in which magnesium is bound to the amino acid glycine. This organic form of magnesium is valued for its good absorption and gentle effect on the digestive system. It has no laxative effect and does not irritate the digestive tract, making it an excellent choice for people with a sensitive stomach and for anyone who wants to avoid the common digestive problems associated with other forms of magnesium.</p><p><strong>WHY CHOOSE MAGNESIUM BISGLYCINATE?</strong></p><ul><li><p>Organic form of magnesium with good bioavailability</p></li><li><p>Suitable for topping up your daily magnesium intake</p></li><li><p>Contributes to normal muscle and nervous system function</p></li><li><p>Helps reduce tiredness and fatigue</p></li><li><p>Involved in energy metabolism</p></li><li><p>Contributes to the maintenance of healthy bones and electrolyte balance</p></li></ul><p>A varied and balanced diet and a healthy lifestyle are recommended.</p><p><strong>Net quantity:</strong> 120 capsules</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 4 capsules.' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Take 4 capsules with a glass of water after training or before bed.

WARNINGS: Do not exceed the recommended daily dose. Food supplements are not a substitute for a balanced and varied diet and a healthy lifestyle. Keep out of reach of young children.

STORAGE: Store in a dark, dry place at a temperature below 25°C.' ELSE InstructionsForUseDescriptionEn END
WHERE Product_Id = 2305;

