-- Product_Id: 2307 (LONG LEGGINGS, TAJA)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'LONG LEGGINGS, TAJA' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>TAJA women’s leggings in modern ribbed fabric</p></li><li><p>For complete comfort and an attractive look</p></li><li><p>Made from slightly thicker fabric</p></li><li><p>Squat-proof</p></li><li><p>Available in 2 different colours</p></li><li><p>The Taja sports top, short- and long-sleeved tops and short leggings are also available</p></li></ul><p>TAJA women’s leggings are suitable for wearing during training or in your free time. They are made of modern ribbed fabric that is slightly thicker and provides complete comfort while giving an attractive look. The high waist and the elastic hem at the bottom of the legs ensure comfort during exercise and stop the leggings slipping down, so they stay in place. The fabric is squat-proof, so you can do squats without worry. The look of the leggings is further accentuated by a drawstring at the waist.</p><p>The model in the photo is 173 cm tall and wears size M.</p><p><strong>MAIN FEATURES:</strong></p><ul><li><p>Made of modern ribbed fabric for an attractive look</p></li><li><p>Soft and comfortable</p></li><li><p>Extremely stretchy</p></li><li><p>Made from slightly thicker fabric</p></li><li><p>Squat-proof</p></li><li><p>Mid-high waist</p></li><li><p>With a drawstring at the waist</p></li><li><p><strong>Composition:</strong> 90% nylon, 10% spandex</p></li><li><p><strong>Available colours:</strong> black, blue</p></li></ul>"]' ELSE DescriptionEn END
WHERE Product_Id = 2307;

