-- Product_Id: 2317 (SPORTS BRA NELLY)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'SPORTS BRA NELLY' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>NELLY women’s sports bra</p></li><li><p>Perfect fit and support for the bust</p></li><li><p>With thin straps</p></li><li><p>Multi-purpose use</p></li><li><p>Available in 3 colours</p></li><li><p>NELLY short and long leggings are also available</p></li></ul><p>The NELLY women’s sports bra is made of soft, stretchy fabric that allows exceptional freedom of movement, even during the most intense sports activities. It can be worn as underwear or as a standalone top. It has soft, thin pads that shape the bust nicely and can be removed for an even lighter feel. Unlike other sports tops, the straps are thinner and join at the back.</p><p>The model in the photo is 168 cm tall and wears size S.</p><p><strong>MAIN FEATURES:</strong></p><ul><li><p>Suitable for sports activities and leisure</p></li><li><p>The double-layer fabric and wider elastic band under the bust provide extra support</p></li><li><p>Seamless fabric for complete comfort</p></li><li><p>Effectively wicks away sweat and keeps skin feeling dry</p></li><li><p>Made from a material that allows maximum freedom of movement</p></li><li><p>With thin, adjustable-length straps</p></li><li><p><strong>Composition:</strong> 90% nylon, 10% spandex</p></li><li><p><strong>Available colours:</strong> turquoise, orange</p></li><li><p>NELLY short and long leggings are also available</p></li></ul>"]' ELSE DescriptionEn END
WHERE Product_Id = 2317;

-- Product_Id: 2318 (BATTERY CREATINE, 250g)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'BATTERY CREATINE, 250g' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li>100% pure creatine</li><li>Unflavoured</li><li>Increases physical performance</li><li>One of the most popular food supplements among athletes</li><li>Made in our own production facilities in the EU</li></ul><p><strong>Creatine powder. Food supplement. Unflavoured.</strong></p><p>Battery Creatine consists of 100% pure creatine, one of the most popular food supplements among athletes. One of the biggest challenges we face in training is the depletion of our energy reserves, which can limit our performance. Creatine increases physical performance in successive bursts of short-term, high-intensity exercise (the beneficial effect is obtained with a daily intake of 3 g of creatine).</p><p><strong>Safe and high quality – made in our own production facilities in the EU</strong></p><ul><li>Proven ingredients, with no unnecessary additives.</li><li>Made in the EU to high quality and safety standards.</li></ul><p><em>A balanced and varied diet and a healthy lifestyle are important.</em></p><p><strong>Net quantity:</strong> 500 g</p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 1 full scoop (3.4 g). Use a scale for accurate measuring.' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Consume 20 minutes before training. On non-training days, consume in the morning on an empty stomach. The maximum daily amount is 1 serving. The product is intended for adults who engage in high-intensity physical activity.

WARNINGS: Do not exceed the recommended daily dose. The product should not be used as a substitute for a balanced diet. Keep out of reach of children!

STORAGE: Store in a dark, dry place at a temperature below 25°C.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Dissolve 1 serving in 250 ml of lukewarm water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2318;

-- Product_Id: 2319 (PROTEINI.SI 100% PURE CREATINE (FLAVOURED))
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI 100% PURE CREATINE (FLAVOURED)' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>A simple, effective and reliable creatine food supplement</p></li><li><p>3000 mg of pure creatine per serving</p></li><li><p>For everyone who wants more strength and noticeable progress</p></li><li><p>Developed and made in our own production facilities in the EU</p></li><li><p>58 servings for long-term training support and continuous progress</p></li></ul><p><strong>Improve your performance with uncompromising purity you can trust.</strong></p><p><strong>Ready to take your training to the next level?</strong></p><p>Proteini.si 100% Pure Creatine with a refreshing lemon flavour is made for everyone who expects more from their body. Each serving provides 3000 mg of pure creatine, which increases physical performance in successive bursts of short-term, high-intensity exercise – exactly in the moments that lead to real progress.</p><p>Thanks to quick and easy preparation, it is ideal to take before training, but also on non-training days, when you still need energy and focus.</p><p>Complete purity of ingredients and verified production in the EU ensure top quality you can feel with every rep.</p><p><strong>WHY CHOOSE PROTEINI.SI 100% PURE CREATINE?</strong></p><ul><li><p>3000 mg of pure creatine per serving – the optimal amount to support physical performance during intense exertion</p></li><li><p>Refreshing lemon flavour, ready in just a few seconds</p></li><li><p>Developed and made in our own production facilities in the EU – for reliable quality and pure ingredients</p></li></ul><p>If you train hard, choose a supplement that supports your performance.</p><p><strong>Proteini.si 100% Pure Creatine – your support for strength, explosiveness and progress.</strong></p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 4.2 g (1 full scoop – use a scale for accurate measuring).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Consume 20 minutes before training. On non-training days, consume in the morning on an empty stomach. The maximum daily amount is 1 serving (4.2 g). The product is intended for adults who engage in high-intensity physical activity.

WARNINGS: Do not exceed the recommended daily dose. Food supplements are not a substitute for a balanced and varied diet and a healthy lifestyle. Keep out of reach of young children!

STORAGE: Store in a dark, dry place at a temperature below 25°C.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Dissolve 4.2 g of powder in 250 ml of lukewarm water.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2319;

