-- Product_Id: 2322 (NUTREND CARNITINE DRINK, 750ml, LEMON)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'NUTREND CARNITINE DRINK, 750ml, LEMON' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li>A refreshing ready-to-drink beverage</li><li>Sugar-free</li><li>1000 mg L-carnitine per serving</li><li>With caffeine and taurine</li></ul><p><strong>Flavoured non-alcoholic drink with sweeteners, with added L-carnitine, taurine and caffeine.</strong></p><p><strong>Carbonated flavoured non-alcoholic drink with sweeteners, with added L-carnitine, taurine and caffeine.</strong><br>(flavours: Raspberry, Cola, Mojito, Mango &amp; Coconut, Lavender, Strawberry &amp; Mint)</p><p>A refreshing, sugar-free ready-to-drink beverage containing 1000 mg of L-carnitine, with added stimulating ingredients such as caffeine and taurine. The drink is an excellent choice for supporting physical performance and helps maintain proper hydration during training. Thanks to its light, refreshing taste, it fits easily into your training routine and helps you drink fluids regularly.</p><ul><li>1000 mg L-carnitine</li><li>1000 mg taurine</li><li>40 mg caffeine</li><li>Sugar-free</li></ul><p><strong>RECOMMENDED USE:</strong> 1 bottle per day. Drink 20–30 minutes before physical activity. It can also be used during training.</p><p><strong>USE:</strong> Once opened, consume the product within 24 hours.</p><p><strong>Suitable for athletes, with sweeteners.</strong> Intended for particular nutritional needs. Not intended for children, pregnant or breastfeeding women. Keep out of reach of children! Store in a dry place at a temperature up to 25°C, protected from direct sunlight. Do not freeze. Contains caffeine. Not suitable for registered athletes. The manufacturer is not liable for damage caused by improper use or storage.</p><p><strong>Net quantity:</strong> 750 ml</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2322;

-- Product_Id: 2325 (DYMATIZE CREATINE MONOHYDRATE 300g)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'DYMATIZE CREATINE MONOHYDRATE 300g' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<p>Push past your training limits! Looking for an extra boost for better performance during intense workouts? Creatine increases physical performance in short-term, high-intensity exercise such as strength training.<br><br>Like you, Dymatize makes no compromises on quality and uses only Creapure® – high-quality creatine monohydrate.<br><br>Creatine is a natural substance found in the body. It plays a key role in transporting and storing energy in all cells. A daily intake of 3 g of creatine over a period of at least 4 weeks has been shown to increase muscle creatine content.<br><br>Unflavoured and highly pure, Dymatize® CREATINE MONOHYDRATE, mixed with water or another caffeine-free drink, is the perfect choice for periods of intense training.</p><p><br></p><p>Net quantity: 300g</p><p></p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'2 scoops daily. Consume as part of a varied and balanced diet and a healthy lifestyle.' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'Creatine is not suitable for children and adolescents. It is intended only for adults who engage in intense physical activity. Food supplements are not a substitute for a varied and balanced diet and a healthy lifestyle. Do not exceed the recommended daily dose. Keep out of reach of children.' ELSE InstructionsForUseDescriptionEn END
WHERE Product_Id = 2325;

-- Product_Id: 2326 (APPLIED NUTRITION CREATINE MONOHYDRATE, 250G)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'APPLIED NUTRITION CREATINE MONOHYDRATE, 250G' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<p>Applied Nutrition Creatine Monohydrate is micronised creatine powder. The unflavoured variant contains 100% creatine monohydrate, with 5 g of creatine per serving.</p><p><br>Available in packs of:<br>- 250 g (50 servings)<br>- 500 g (100 servings)<br>- 1 kg (200 servings)<br></p><p>&nbsp;Use the Informed Sport tested batch register for Applied Nutrition Creatine Monohydrate Professional to check the batch number printed on the pack: https://sport.wetestyoutrust.com/ja/node/1146294&nbsp;&nbsp;</p><p>KEY ADVANTAGES:<br><br>- Increased strength and power: Helps you lift heavier weights and do more reps, contributing to greater muscle growth over time.<br>- Improved sports performance: Ideal for high-intensity sports and activities, to improve overall performance and endurance.<br>- Improved muscle recovery: Helps reduce muscle soreness and speed up recovery, allowing more frequent training.<br>- Support for lean muscle mass: Promotes the growth of lean muscle tissue without unnecessary gains in body fat.<br>- Mixes easily with water.<br>- Tested for athletes by Informed Sport.<br>- Halal-certified product.</p><p></p><p></p>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Add 1 serving (5 g) to water, shake and drink. Use 1–2 times a day, preferably just before and after physical activity. After 8 weeks of continuous use, take a 1-week break, then repeat the cycle.' ELSE InstructionsForUseEn END
WHERE Product_Id = 2326;

