-- Product_Id: 2330 (RABEKO SAUCE, 350ml)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'RABEKO SAUCE, 350ml' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<p><strong>Rabeko Zero sauces – great taste without unnecessary compromises</strong></p><p>Want to enrich your favourite meals with tasty sauces without unnecessary calories, sugars and fats? Then Rabeko Zero sauces are the right choice! With a variety of flavours and a light composition, they are a great way to enjoy your favourite meals without compromising your diet.</p><p><strong>WHAT MAKES THEM SUCH A GOOD CHOICE?</strong></p><ul><li><p>Low calorie value</p></li><li><p>Reduced sugar content compared with classic sauces</p></li><li><p>Light composition, with no unnecessary additives</p></li><li><p>No artificial colours</p></li><li><p>Fit perfectly into a balanced, mindful lifestyle</p></li></ul><p><strong>PERFECT WITH:</strong></p><ul><li><p>Fries and snacks made in an air fryer</p></li><li><p>Burgers, tortillas, toasties and omelettes</p></li><li><p>Grilled food and various main dishes</p></li><li><p>As a topping or dip for your favourite snacks</p></li></ul><p>Whether you train, watch your diet or simply want to make more mindful choices, Rabeko Zero sauces let you enjoy your favourite flavours without compromise. Tasty, light and ideal for every day!</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2330;

-- Product_Id: 2331 (PROTEINI.SI ULTIMATE GRIPS)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'PROTEINI.SI ULTIMATE GRIPS' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Makes lifting weights easier</p></li><li><p>Provides a more secure grip</p></li><li><p>Offers wrist support</p></li><li><p>Easy to use</p></li></ul><p><strong>Proteini.si Ultimate Grips</strong> are an advanced training accessory designed to improve your grip and maximise your training performance and results.</p><p><strong>Proteini.si Ultimate Grips</strong> have a durable rubber surface that provides a stable, secure grip. The unique rubber surface wraps around the bar and adapts to its shape, allowing a firm hold when lifting weights. The adjustable Velcro strap provides extra protection and comfort for the palms and wrists.</p>"]' ELSE DescriptionEn END
WHERE Product_Id = 2331;

-- Product_Id: 2334 (BOLERO)
UPDATE dbo.Products SET
    NameEn = CASE WHEN ISNULL(NameEn, N'') = N'' THEN N'BOLERO' ELSE NameEn END,
    DescriptionEn = CASE WHEN ISNULL(DescriptionEn, N'') = N'' THEN N'["<ul><li><p>Instant flavoured fruit drink</p></li><li><p>Wide choice of flavours</p></li><li><p>With added vitamin C</p></li><li><p>Sugar, gluten and lactose free</p></li><li><p>1 sachet = 1.5 L of drink</p></li><li><p>ENERGY variant: 1 sachet = 500 ml of drink</p></li></ul><p>Refresh yourself from the inside with BOLERO CLASSIC. Enjoy the wide choice of flavours at any time of day.</p><p><strong>BOLERO CLASSIC:</strong></p><ul><li><p>With added vitamin C</p></li><li><p>Sugar, gluten and lactose free</p></li><li><p>No artificial colours or preservatives</p></li><li><p>1 sachet = 1.5 L of drink</p></li></ul><p><strong>BOLERO ENERGY:</strong></p><ul><li><p>With added caffeine and taurine for more energy</p></li><li><p>Sugar, gluten and lactose free</p></li><li><p>No artificial colours or preservatives</p></li><li><p>1 sachet = 500 ml of drink</p></li></ul><p><strong>DID YOU KNOW THAT BOLERO DRINKS:</strong></p><ul><li><p>Contain no sugar</p></li><li><p>Are affordable and offer a wide choice of flavours</p></li><li><p>Can be made with sparkling water or ordinary tap water</p></li><li><p>Are low in calories</p></li><li><p>Let you adjust the amount of water yourself, depending on how intense you want the flavour</p></li><li><p>Are a tasty choice for anyone watching their diet</p></li><li><p>Are practically packed, so you can take them anywhere – to work, training or on holiday</p></li><li><p>Let you create endless flavour combinations by mixing two or more different flavours</p></li></ul>"]' ELSE DescriptionEn END,
    InstructionsForUseEn = CASE WHEN ISNULL(InstructionsForUseEn, N'') = N'' THEN N'Serving size: 1 sachet (9 g / 8 g).' ELSE InstructionsForUseEn END,
    InstructionsForUseDescriptionEn = CASE WHEN ISNULL(InstructionsForUseDescriptionEn, N'') = N'' THEN N'STORAGE: Store in a dry place at a temperature of 15–25°C.' ELSE InstructionsForUseDescriptionEn END,
    InstructionsOnHowToUseItEn = CASE WHEN ISNULL(InstructionsOnHowToUseItEn, N'') = N'' THEN N'Dissolve 1 serving in 1.5 L of cold water (dissolve the ENERGY flavour in 250 ml of cold water). You can adjust the amount of water depending on the desired intensity of flavour.' ELSE InstructionsOnHowToUseItEn END
WHERE Product_Id = 2334;

